import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        List<Integer> prices = List.of(250, 199, 640, 75, 520, 310);
        int[] stock = {12, 40, 7, 33};

        int total = prices.stream().mapToInt(Integer::intValue).sum();
        double avg = prices.stream().mapToInt(Integer::intValue).average().orElse(0.0);
        long over300 = prices.stream().filter(p -> p > 300).count();
        int maxStock = Arrays.stream(stock).max().getAsInt();
        int squares = IntStream.rangeClosed(1, 10).map(i -> i * i).sum();
        int firstOver500 = prices.stream().filter(p -> p > 500).findFirst().orElse(-1);

        int[] arr = prices.stream().mapToInt(Integer::intValue).toArray();
        List<Integer> back = Arrays.stream(arr).boxed().collect(Collectors.toList());

        System.out.println("Total: " + total);
        System.out.printf("Average: %.2f%n", avg);
        System.out.println("Over 300: " + over300);
        System.out.println("Max stock: " + maxStock);
        System.out.println("Sum of squares: " + squares);
        System.out.println("First over 500: " + firstOver500);
        System.out.println("Array: " + Arrays.toString(arr));
        System.out.println("Back: " + back);
    }
}

