import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<String> names = List.of("Ava", "Liam", "Noah", "Mia", "Lucas", "Ella", "Max");

        String shortNames = names.stream()
                .filter(n -> n.length() == 3)
                .collect(Collectors.joining(", "));
        boolean anyL = names.stream().anyMatch(n -> n.startsWith("L"));
        boolean allLong = names.stream().allMatch(n -> n.length() >= 3);
        boolean noneEmpty = names.stream().noneMatch(String::isEmpty);

        Map<Integer, Long> byLength = names.stream()
                .collect(Collectors.groupingBy(String::length, TreeMap::new, Collectors.counting()));
        Set<Character> letters = names.stream()
                .map(n -> n.charAt(0))
                .collect(Collectors.toCollection(TreeSet::new));

        System.out.println("Short: " + shortNames);
        System.out.println("Any L: " + anyL);
        System.out.println("All 3+: " + allLong);
        System.out.println("None empty: " + noneEmpty);
        System.out.println("By length: " + byLength);
        System.out.println("Letters: " + letters);
    }
}

