import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<String> cities = List.of("Seattle", "Boston", "Denver", "Austin", "Salem",
                "Dallas", "Spokane", "Ely");

        String sCities = cities.stream()
                .filter(c -> c.startsWith("S"))
                .collect(Collectors.joining(", "));
        boolean anyD = cities.stream().anyMatch(c -> c.startsWith("D"));
        boolean allLong = cities.stream().allMatch(c -> c.length() > 3);
        boolean noneBlank = cities.stream().noneMatch(String::isBlank);

        Map<Character, Long> byLetter = cities.stream()
                .collect(Collectors.groupingBy(c -> c.charAt(0), TreeMap::new, Collectors.counting()));
        Set<Integer> lengths = cities.stream()
                .map(String::length)
                .collect(Collectors.toCollection(TreeSet::new));

        System.out.println("S cities: " + sCities);
        System.out.println("Any D: " + anyD);
        System.out.println("All longer than 3: " + allLong);
        System.out.println("None blank: " + noneBlank);
        System.out.println("By letter: " + byLetter);
        System.out.println("Lengths: " + lengths);
    }
}
